def align_intraday(df, sec):
    """Yahoo adds a half-finished 'latest price' row whose time is the last trade time (e.g. 10:44:12), not a candle
    start. Such rows used to show up as tiny dashes next to the real candle. Merge every row into its own candle."""
    t = df["time"].astype("int64").values
    day0 = (t + SHIFT) // 86400 * 86400 - SHIFT
    start = day0 + 9 * 3600 + 15 * 60                        # NSE session starts 09:15, candles are 09:15 + n x sec
    end = day0 + 15 * 3600 + 30 * 60
    b = start + np.maximum(0, (t - start) // sec) * sec
    b = np.where(b >= end, b - ((b - end) // sec + 1) * sec, b)     # a tick at/after 15:30 belongs to the last candle
    if (b == t).all():
        return df
    g = df.assign(time=b).groupby("time", sort=True)
    out = g.agg(open=("open", "first"), high=("high", "max"), low=("low", "min"), close=("close", "last")).reset_index()
    out["time"] = out["time"].astype(int)
    return out


def align_period(df, interval):
    """1D / 1W / 1M: Yahoo adds an extra 'latest price' row (time = last trade time) next to the real day/week/month row.
    Every new tick then drew one more tiny candle. Merge all rows of the same day / week / month into ONE candle."""
    t = df["time"].astype("int64").values
    day = (t + SHIFT) // 86400
    if interval == "1d":
        key = day
    elif interval == "1wk":
        key = day - (day + 3) % 7                              # Monday of that week (1-Jan-1970 was a Thursday)
    else:
        ts = pd.to_datetime(t + SHIFT, unit="s")
        key = ts.year * 12 + ts.month
    key = np.asarray(key)
    if len(np.unique(key)) == len(key):
        return df
    out = (df.assign(k=key).groupby("k", sort=True)
             .agg(time=("time", "min"), open=("open", "first"), high=("high", "max"),
                  low=("low", "min"), close=("close", "last")).reset_index(drop=True))
    out["time"] = out["time"].astype(int)
    return out


yahoo_cool = [0.0]                       # Yahoo answered "429 too many requests" -> everybody slows down until this time


def fetch(tf, sym=DEFAULT_SYM, recent=False):
    """recent=True: only the last session (small answer, much faster) - used for the 0.5 s live updates."""
    if tf == "4h":                       # Yahoo has no 4h: built from 1h candles (09:15-13:15 and 13:15-15:30, like Indian platforms)
        h = fetch("1h", sym, recent)
        out = resample_4h(h).drop(columns="end")
        out.attrs = dict(h.attrs)
        return out
    interval, rng, _ = TFS[tf]
    if recent:
        rng = "1d"
    last_err = None
    for host in ("query1", "query2"):
        try:
            url = f"https://{host}.finance.yahoo.com/v8/finance/chart/{urlquote(sym, safe='')}"
            r = http.get(url, params={"interval": interval, "range": rng, "includePrePost": "false"},
                         headers=HEADERS, timeout=8)
            r.raise_for_status()
            res = r.json()["chart"]["result"][0]
            q = res["indicators"]["quote"][0]
            df = pd.DataFrame({"time": res["timestamp"], "open": q["open"], "high": q["high"],
                               "low": q["low"], "close": q["close"]}).dropna()
            df["time"] = df["time"].astype(int)
            df = df.drop_duplicates("time", keep="last").sort_values("time").reset_index(drop=True)
            if interval not in ("1d", "1wk", "1mo"):
                df = align_intraday(df, TFS[tf][2])
            else:
                df = align_period(df, interval)
            if len(df) < (1 if recent else 30):
                raise RuntimeError("Yahoo returned too little data")
            df.attrs["tick"] = res.get("meta", {}).get("regularMarketTime")
            return df
        except Exception as e:
            last_err = e
            if "429" in str(e):
                yahoo_cool[0] = time.time() + 20
    raise RuntimeError(f"Yahoo data error: {last_err}")


def supertrend(df):
    hl2 = (df.high + df.low) / 2
    tr = pd.concat([df.high - df.low, (df.high - df.close.shift()).abs(),
                    (df.low - df.close.shift()).abs()], axis=1).max(axis=1)
    atr = tr.ewm(alpha=1 / ST_PERIOD, adjust=False).mean()
    ub, lb, c = (hl2 + ST_MULT * atr).values, (hl2 - ST_MULT * atr).values, df.close.values
    fub, flb, d = ub.copy(), lb.copy(), np.ones(len(df))
    for i in range(1, len(df)):
        fub[i] = ub[i] if (ub[i] < fub[i - 1] or c[i - 1] > fub[i - 1]) else fub[i - 1]
        flb[i] = lb[i] if (lb[i] > flb[i - 1] or c[i - 1] < flb[i - 1]) else flb[i - 1]
        d[i] = (-1 if c[i] < flb[i] else 1) if d[i - 1] == 1 else (1 if c[i] > fub[i] else -1)
    return d, np.where(d == 1, flb, fub)


def simulate(df, d, intraday):
    """Enter on a Supertrend flip confirmed by EMA20; exit on opposite flip, SL, or (intraday) end of day."""
    close, high, low, ema = df.close.values, df.high.values, df.low.values, df.ema.values
    opn = df.open.values
    tr = pd.concat([df.high - df.low, (df.high - df.close.shift()).abs(),
                    (df.low - df.close.shift()).abs()], axis=1).max(axis=1)
    atr = tr.rolling(14, min_periods=1).mean().values
    day = ((df.time.values + SHIFT) // 86400)
    trades, i, n = [], 1, len(df)
    while i < n:
        flip = d[i] != d[i - 1]                  # also a flip on the first candle of the day (gap open) is a signal, like on the chart
        long_ok = flip and d[i] == 1 and close[i] > ema[i]
        short_ok = flip and d[i] == -1 and close[i] < ema[i]
        if not (long_ok or short_ok):
            i += 1
            continue
        side = 1 if long_ok else -1
        entry = close[i]
        risk = SL_ATR_MULT * atr[i] if SL_ATR_MULT else entry * SL_PCT / 100
        sl = entry - side * risk                 # fixed at entry (not trailing)
        j, exit_px, why = i + 1, None, None
        while j < n:
            if intraday and day[j] != day[i]:
                exit_px, why, j = close[j - 1], "EOD", j - 1
                break
            hit = low[j] <= sl if side == 1 else high[j] >= sl
            if hit:                                  # a gap through the stop fills at the open, not at the stop
                exit_px, why = (min(sl, opn[j]) if side == 1 else max(sl, opn[j])), "SL"
                break
            if d[j] != d[i]:
                exit_px, why = close[j], "FLIP"
                break
            j += 1
        if exit_px is None:
            trades.append(dict(side=side, i=i, entry=entry, j=None, exit=close[-1], why="OPEN", sl=sl))
            break
        trades.append(dict(side=side, i=i, entry=entry, j=j, exit=exit_px, why=why, sl=sl))
        i = j + 1 if why in ("SL", "EOD") else j
    return trades


def market_status():
    ist = dt.datetime.now(dt.timezone.utc) + dt.timedelta(seconds=SHIFT)
    open_now = ist.weekday() < 5 and dt.time(9, 15) <= ist.time() <= dt.time(15, 30)
    return "OPEN" if open_now else "CLOSED"


def market_structure(df, n_closed, t, N):
    """Swing highs/lows (pivot with N candles each side) and breakouts of them on CLOSED candles.
    BOS = close breaks the last swing in the trend direction; CHoCH = break against the prior trend."""
    high, low, close = df.high.values, df.low.values, df.close.values
    ph = pl = None
    trend, events = 0, []
    for i in range(N, n_closed):
        j = i - N                                   # pivot at j is confirmed only now (no look-ahead)
        if j >= N:
            if high[j] >= high[j - N:j + N + 1].max():
                ph = (j, float(high[j]))
            if low[j] <= low[j - N:j + N + 1].min():
                pl = (j, float(low[j]))
        c = float(close[i])
        if ph and c > ph[1]:
            events.append(dict(kind="CHoCH" if trend == -1 else "BOS", up=True, t0=t[ph[0]], t1=t[i],
                               price=round(ph[1], 2), i0=ph[0], i1=i))
            trend, ph = 1, None
        elif pl and c < pl[1]:
            events.append(dict(kind="CHoCH" if trend == 1 else "BOS", up=False, t0=t[pl[0]], t1=t[i],
                               price=round(pl[1], 2), i0=pl[0], i1=i))
            trend, pl = -1, None
    return dict(events=events[-14:], trend=trend, _all=events,
                high=dict(t=t[ph[0]], price=round(ph[1], 2)) if ph else None,
                low=dict(t=t[pl[0]], price=round(pl[1], 2)) if pl else None)


def smc_zones(df, n_closed, t, N, atr, events):
    """Smart-money zones on CLOSED candles (the running candle only decides if a zone is already used up).
    Order block (OB) = last opposite candle before the move that broke structure (BOS/CHoCH).
    Fair value gap (FVG) = 3-candle gap that price has not filled yet.
    Premium / Discount = upper / lower half of the latest swing range (equilibrium = 50%)."""
    op, high, low, close = df.open.values, df.high.values, df.low.values, df.close.values
    n = len(df)
    price, a = float(close[-1]), float(atr[-1])
    lim = 15 * a
    obs = []
    for e in events:
        i0, i1 = e["i0"], e["i1"]
        k = None
        for q in range(i1 - 1, max(i0 - 1, i1 - 25), -1):          # walk back from the break to the swing
            if (close[q] < op[q]) if e["up"] else (close[q] > op[q]):
                k = q
                break
        if k is None:
            continue
        lo, hi = float(low[k]), float(high[k])
        dead = tested = False
        for m in range(i1 + 1, n):
            if (close[m] < lo) if e["up"] else (close[m] > hi):
                dead = True                                          # closed through the block: no longer valid
                break
            if (low[m] <= hi) if e["up"] else (high[m] >= lo):
                tested = True                                        # price came back to the block (mitigated once)
        if not dead and abs((lo + hi) / 2 - price) <= lim:
            obs.append(dict(up=bool(e["up"]), t0=t[k], lo=round(lo, 2), hi=round(hi, 2), tested=tested, kind=e["kind"]))
    obs = [o for o in obs if o["up"]][-2:] + [o for o in obs if not o["up"]][-2:]
    fvgs = []
    for i in range(2, n_closed):
        if low[i] > high[i - 2]:                                     # bullish gap
            lo, hi, up = float(high[i - 2]), float(low[i]), True
        elif high[i] < low[i - 2]:                                   # bearish gap
            lo, hi, up = float(high[i]), float(low[i - 2]), False
        else:
            continue
        if hi - lo < 0.3 * float(atr[i]):
            continue
        for m in range(i + 1, n):                                    # price coming back fills the gap (from its near side)
            if up:
                if low[m] <= lo:
                    hi = lo
                    break
                hi = min(hi, float(low[m]))
            else:
                if high[m] >= hi:
                    lo = hi
                    break
                lo = max(lo, float(high[m]))
        if hi - lo >= 0.15 * a and abs((lo + hi) / 2 - price) <= lim:
            fvgs.append(dict(up=up, t0=t[i - 1], lo=round(lo, 2), hi=round(hi, 2)))
    fvgs = [f for f in fvgs if f["up"]][-2:] + [f for f in fvgs if not f["up"]][-2:]
    pd_ = None
    jh = jl = None
    for j in range(N, n_closed - N):
        if high[j] >= high[j - N:j + N + 1].max():
            jh = j
        if low[j] <= low[j - N:j + N + 1].min():
            jl = j
    if jh is not None and jl is not None and high[jh] > low[jl]:
        hi, lo = float(high[jh]), float(low[jl])
        eq = (hi + lo) / 2
        pd_ = dict(hi=round(hi, 2), lo=round(lo, 2), eq=round(eq, 2), t0=min(t[jh], t[jl]),
                   zone="PREMIUM" if price > eq else "DISCOUNT")
    return dict(obs=obs, fvgs=fvgs, pd=pd_, end=t[n - 1])


def liquidity_zones(df, n_closed, t, N, atr):
    """LIVE liquidity. Levels = swing highs/lows (stop-losses sit there), found on CLOSED candles only.
    EQH/EQL = two swings at (almost) the same level. Sweep = a candle pokes beyond a level but closes back
    inside (stop-hunt); the running candle is checked too (live=True) so you see it as it happens."""
    high, low, close = df.high.values, df.low.values, df.close.values
    n = len(df)
    levels, sweeps = [], []
    for i in range(N, n):
        live = i >= n_closed                           # the candle that is still forming
        if not live:
            j = i - N
            if j >= N:
                tol = 0.25 * float(atr[i])
                for side, arr, ok in (("H", high, high[j] >= high[j - N:j + N + 1].max()),
                                      ("L", low, low[j] <= low[j - N:j + N + 1].min())):
                    if not ok:
                        continue
                    lv = dict(side=side, j=j, price=float(arr[j]), eq=False, done=False)
                    for o in levels:                   # equal high / equal low with an earlier untouched swing
                        if o["side"] == side and not o["done"] and abs(o["price"] - lv["price"]) <= tol:
                            o["eq"] = lv["eq"] = True
                    levels.append(lv)
                levels = levels[-80:]
        for lv in levels:
            if lv["done"]:
                continue
            if lv["side"] == "H" and high[i] > lv["price"]:
                lv["done"] = True
                if close[i] < lv["price"]:
                    sweeps.append(dict(up=False, eq=lv["eq"], live=live, t0=t[lv["j"]], t1=t[i],
                                       price=round(lv["price"], 2)))
            elif lv["side"] == "L" and low[i] < lv["price"]:
                lv["done"] = True
                if close[i] > lv["price"]:
                    sweeps.append(dict(up=True, eq=lv["eq"], live=live, t0=t[lv["j"]], t1=t[i],
                                       price=round(lv["price"], 2)))
    # levels that are still waiting to be hit: nearest 2 above, nearest 2 below, and every EQH/EQL close by
    price, lim = float(close[-1]), 12 * float(atr[-1])
    open_lv = [lv for lv in levels if not lv["done"] and abs(lv["price"] - price) <= lim]
    above = sorted([lv for lv in open_lv if lv["side"] == "H" and lv["price"] > price], key=lambda x: x["price"])[:2]
    below = sorted([lv for lv in open_lv if lv["side"] == "L" and lv["price"] < price], key=lambda x: -x["price"])[:2]
    chosen, seen = [], set()
    for lv in above + below + [x for x in open_lv if x["eq"]]:
        k = (lv["side"], round(lv["price"], 1))
        if k not in seen:
            seen.add(k)
            chosen.append(dict(side=lv["side"], eq=lv["eq"], price=round(lv["price"], 2), t0=t[lv["j"]]))
    return dict(sweeps=sweeps[-12:], levels=chosen[:8], end=t[n - 1])


def sr_levels(df, n_closed, N, atr):
    """All support/resistance zones = price areas where swing highs AND swing lows repeatedly formed (>= 2 touches)."""
    high, low, close = df.high.values, df.low.values, df.close.values
    pv = []
    for j in range(N, n_closed - N):
        if high[j] >= high[j - N:j + N + 1].max():
            pv.append(float(high[j]))
        if low[j] <= low[j - N:j + N + 1].min():
            pv.append(float(low[j]))
    pv.sort()
    tol = 0.5 * float(atr[-1])
    clusters, cur = [], []
    for p in pv:
        if cur and p - cur[0] > tol:
            clusters.append(cur)
            cur = []
        cur.append(p)
    if cur:
        clusters.append(cur)
    return [dict(price=round(sum(c) / len(c), 2), touches=len(c)) for c in clusters if len(c) >= 2]


def sr_zones(df, n_closed, atr):
    """Supply / demand zones: a CONSOLIDATION (3-8 tight candles) followed by a BIG move out of it.
    Move up out of the base = demand zone (support box); move down = supply zone (resistance box).
    The box is the base range. It is dropped when a candle closes through it; 'tested' = price already came back once."""
    high, low, close = df.high.values, df.low.values, df.close.values
    t = (df["time"].astype("int64").values + SHIFT)
    n = len(df)
    zs = []
    i = 8
    while i < n_closed - 1:
        a = float(atr[i - 1])
        found = None
        for K in (8, 7, 6, 5, 4, 3):                                 # longest tight base that ends right before candle i
            hi, lo = float(high[i - K:i].max()), float(low[i - K:i].min())
            if hi - lo <= 1.6 * a:
                up = float(close[i:i + 3].max()) - hi
                dn = lo - float(close[i:i + 3].min())
                if up >= 1.8 * a and up > dn and close[i] > hi:        # candle i is the one that leaves the base
                    found = (True, K, lo, hi, up / a)
                elif dn >= 1.8 * a and dn > up and close[i] < lo:
                    found = (False, K, lo, hi, dn / a)
                break
        if found:
            up, K, lo, hi, mult = found
            dead = tested = False
            for m in range(i + 3, n):
                if (close[m] < lo) if up else (close[m] > hi):
                    dead = True                                      # closed through the zone: finished
                    break
                if (low[m] <= hi) if up else (high[m] >= lo):
                    tested = True
            dup = any(z["up"] == up and lo <= z["hi"] and hi >= z["lo"] for z in zs)
            if not dead and not dup:
                zs.append(dict(up=up, t0=int(t[i - K]), lo=round(lo, 2), hi=round(hi, 2), tested=tested, n=K, mult=round(mult, 1)))
            i += 3
        else:
            i += 1
    price, lim = float(close[-1]), 15 * float(atr[-1])
    zs = [z for z in zs if abs((z["lo"] + z["hi"]) / 2 - price) <= lim]
    dem = sorted([z for z in zs if z["up"]], key=lambda z: abs((z["lo"] + z["hi"]) / 2 - price))[:2]
    sup = sorted([z for z in zs if not z["up"]], key=lambda z: abs((z["lo"] + z["hi"]) / 2 - price))[:2]
    return dem + sup


def sr_pick(lv, price, src):
    """Nearest 3 supports below and 3 resistances above the current price (a level flips side when price crosses it)."""
    sup = sorted([x for x in lv if x["price"] < price], key=lambda x: -x["price"])[:3]
    res = sorted([x for x in lv if x["price"] > price], key=lambda x: x["price"])[:3]
    out = [dict(kind="S", n=i + 1, **x) for i, x in enumerate(sup)] + [dict(kind="R", n=i + 1, **x) for i, x in enumerate(res)]
    return dict(levels=out, src=src)


