quote_cache = {}


def quote(sym):
    """Last price + change vs previous close (cached 8 s per symbol)."""
    c = quote_cache.get(sym)
    if c and time.time() - c["t"] < 8:
        return c["v"]
    try:
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{urlquote(sym, safe='')}"
        r = http.get(url, params={"interval": "1d", "range": "5d", "includePrePost": "false"},
                     headers=HEADERS, timeout=8)
        r.raise_for_status()
        res = r.json()["chart"]["result"][0]
        meta = res["meta"]
        price = float(meta["regularMarketPrice"])
        rt = int(meta.get("regularMarketTime") or time.time())
        today = (rt + SHIFT) // 86400
        prev = None
        for a, b in zip(res.get("timestamp") or [], res["indicators"]["quote"][0]["close"]):
            if b is not None and (a + SHIFT) // 86400 < today:
                prev = float(b)
        if prev is None:
            prev = float(meta.get("chartPreviousClose") or price)
        v = dict(sym=sym, price=round(price, 2), chg=round(price - prev, 2),
                 pct=round((price - prev) / prev * 100, 2) if prev else 0.0)
    except Exception as e:
        v = dict(sym=sym, error=str(e)[:80])
    quote_cache[sym] = {"v": v, "t": time.time()}
    return v


# ---------------------------------------------------------------------------------------------------------
# NEWS MONITOR: headlines from Google News (public RSS, free) about the market and about the stock on the chart.
# New HIGH-impact market headlines are also sent to your phone (same ntfy / Telegram channels as the signal alerts).
# The tags (HIGH / UP / DOWN) are simple KEYWORD rules - a quick filter, not a prediction.
# ---------------------------------------------------------------------------------------------------------
NEWS_ALERTS = os.environ.get("NEWS_ALERTS", "1") != "0"        # NEWS_ALERTS=0 turns the phone alerts for news off
NEWS_EVERY = 150                                              # seconds between checks
NEWS_MARKET_Q = '(Nifty OR Sensex OR "Bank Nifty" OR "Dalal Street" OR RBI OR "Indian stock market") when:1d'
NEWS_ALERT_MAX_AGE = 45 * 60                                  # only alert for headlines younger than this
NEWS_ALERT_PER_HOUR = 6
MARKET_SYMS = ("^NSEI", "^NSEBANK", "^BSESN", "^INDIAVIX")
HIGH_RE = re.compile(r"\b(rbi|repo rate|rate cut|rate hike|fed|fomc|powell|inflation|cpi|gdp|budget|sebi|war|ceasefire|tariffs?|"
                     r"sanctions?|crash(?:es|ed)?|circuit|lockdown|default|recession|opec|crude|results?|earnings|block deal|"
                     r"upgrade[sd]?|downgrade[sd]?|ban(?:ned|s)?|fraud|probe|raid|merger|acquisition|ipo|dividend|bonus|"
                     r"stock split|shutdown|election)\b", re.I)
BULL_RE = re.compile(r"\b(surge[sd]?|rall(?:y|ies|ied)|jump(?:s|ed)?|gain(?:s|ed)?|ris(?:e|es|ing)|soar(?:s|ed)?|record high|"
                     r"all-time high|upgrade[sd]?|beat(?:s)?|strong|bullish|boost|rebound(?:s|ed)?|recover(?:s|ed|y)?)\b", re.I)
BEAR_RE = re.compile(r"\b(fall(?:s|en)?|drop(?:s|ped)?|slump(?:s|ed)?|plunge[sd]?|crash(?:es|ed)?|sell-?off|downgrade[sd]?|"
                     r"miss(?:es|ed)?|loss(?:es)?|bearish|weak|declin(?:e|es|ed)|tumble[sd]?|slide[sd]?|sinks?|fraud|probe|"
                     r"panic|fear)\b", re.I)
news_cache = {}                          # "market" or SYMBOL -> {"items": [...], "t": float, "err": str}
news_seen = set()                        # headlines already known (so a restart does not alert for old news)
news_state = dict(seeded=False, sent=[])
news_lock = threading.Lock()


def news_tag(title):
    hi = bool(HIGH_RE.search(title))
    b, r = len(BULL_RE.findall(title)), len(BEAR_RE.findall(title))
    return hi, ("bull" if b > r else "bear" if r > b else "neu")


def news_parse(xml_text, scope):
    """Google News RSS -> list of dicts, newest first. Pure function (easy to test)."""
    out, seen = [], set()
    root = ET.fromstring(xml_text)
    for it in root.iter("item"):
        title = (it.findtext("title") or "").strip()
        link = (it.findtext("link") or "").strip()
        src = (it.findtext("source") or "").strip()
        if src and title.endswith(" - " + src):
            title = title[:-(len(src) + 3)].strip()
        elif not src and " - " in title:
            title, src = title.rsplit(" - ", 1)
        try:
            ts = int(parsedate_to_datetime(it.findtext("pubDate")).timestamp())
        except Exception:
            ts = int(time.time())
        key = re.sub(r"[^a-z0-9]+", " ", title.lower()).strip()
        if not title or not key or key in seen or not link.lower().startswith(("http://", "https://")):
            continue
        seen.add(key)
        hi, tone = news_tag(title)
        out.append(dict(title=title[:220], link=link, src=src[:60], ts=ts, hi=hi, tone=tone, scope=scope))
    out.sort(key=lambda x: -x["ts"])
    return out[:40]


def news_query(sym):
    if sym in MARKET_SYMS or not sym:
        return "market", NEWS_MARKET_Q
    name = sym.replace(".NS", "").replace(".BO", "")
    return sym, '"%s" (stock OR shares OR NSE OR results) when:2d' % name


def news_get(sym, max_age=NEWS_EVERY):
    """Cached headlines for 'market' or one symbol; keeps the old list if the fetch fails."""
    key, q = news_query(sym)
    c = news_cache.get(key)
    if c and time.time() - c["t"] < max_age:
        return c
    with news_lock:
        c = news_cache.get(key)
        if c and time.time() - c["t"] < max_age:
            return c
        try:
            r = http.get("https://news.google.com/rss/search", params={"q": q, "hl": "en-IN", "gl": "IN", "ceid": "IN:en"},
                         headers=HEADERS, timeout=8)
            r.raise_for_status()
            c = {"items": news_parse(r.content, "market" if key == "market" else "stock"), "t": time.time(), "err": ""}
        except Exception as e:
            old = news_cache.get(key)
            c = {"items": old["items"] if old else [], "t": time.time() - NEWS_EVERY + 20, "err": _hide(str(e))[:120]}
        news_cache[key] = c
        return c


def news_check_alerts(items):
    """Phone alert for NEW high-impact market headlines (the first run only remembers what is already there)."""
    fresh = [x for x in items if x["title"] not in news_seen]
    for x in items:
        news_seen.add(x["title"])
    if len(news_seen) > 3000:
        news_seen.clear()
    if not news_state["seeded"]:
        news_state["seeded"] = True
        return 0
    now = time.time()
    news_state["sent"] = [t for t in news_state["sent"] if now - t < 3600]
    pick = [x for x in fresh if x["hi"] and now - x["ts"] <= NEWS_ALERT_MAX_AGE][:3]
    if not (pick and NEWS_ALERTS and alerts_enabled()) or len(news_state["sent"]) >= NEWS_ALERT_PER_HOUR:
        return 0
    mark = {"bull": "UP", "bear": "DOWN", "neu": ""}
    body = "\n".join("- %s%s (%s)" % (x["title"], (" [%s]" % mark[x["tone"]]) if mark[x["tone"]] else "", x["src"]) for x in pick)
    try:
        ntfy("NEWS: " + pick[0]["title"][:70], body, priority="default", tags="newspaper")
        news_state["sent"].append(now)
        return len(pick)
    except Exception as e:
        print("news alert note:", _hide(str(e)))
        return 0


def news_loop():
    while True:
        try:
            c = news_get("market", max_age=0)
            if not c["err"]:
                news_check_alerts(c["items"])
        except Exception as e:
            print("news note:", _hide(str(e)))
        time.sleep(NEWS_EVERY)


def news_view(sym):
    m = news_get("market")
    items = list(m["items"])
    err = m["err"]
    if sym and sym not in MARKET_SYMS:
        s = news_get(sym)
        items = s["items"] + items
        err = err or s["err"]
    seen, out = set(), []
    for x in sorted(items, key=lambda x: -x["ts"]):
        if x["title"] not in seen:
            seen.add(x["title"])
            out.append(x)
    return dict(items=out[:60], checked=int(m["t"]), err=err, alerts=bool(NEWS_ALERTS and alerts_enabled()))


live_cache = {}                          # "sym|tf" -> {"json": str, "t": float}   (small, polled ~every 0.6 s)
full_t = {}                              # "sym|tf" -> (time of last full build, candle count then)
FULL_EVERY = 4.0                         # structure / liquidity / support-resistance / markers need no faster refresh


base_df = {}                             # "sym|tf" -> (full history frame, time fetched)
BASE_EVERY = 30.0


def get_frame(k, sym, tf):
    """Full history every 30 s; in between only today's candles (small and fast) are fetched and merged into it."""
    b = base_df.get(k)
    now = time.time()
    if b is None or now - b[1] > BASE_EVERY or TFS[tf][2] >= 86400:
        df = fetch(tf, sym)
        base_df[k] = (df, now)
        return df
    rec = fetch(tf, sym, recent=True)
    old = b[0]
    t0 = int(rec["time"].iloc[0])
    df = pd.concat([old[old["time"] < t0], rec], ignore_index=True)
    df.attrs = dict(rec.attrs)
    return df


def refresh_key(k):
    sym, tf = k.rsplit("|", 1)
    with lock_for(k):
        df = get_frame(k, sym, tf)                           # ONE Yahoo request feeds both payloads
        live_cache[k] = {"json": build_live(tf, sym, df), "t": time.time()}
        ft = full_t.get(k)
        if ft is None or time.time() - ft[0] >= FULL_EVERY or ft[1] != len(df):
            cache[k] = {"json": build_json(tf, sym, df), "t": time.time()}
            full_t[k] = (time.time(), len(df))


def refresher():
    """Keeps the data of every chart somebody is watching fresh, so a request is answered instantly."""
    pool = ThreadPoolExecutor(max_workers=6)
    while True:
        keys = [k for k in list(active) if time.time() - active[k] < 90]

        def one(k):
            try:
                refresh_key(k)
            except Exception as e:
                print("refresh note:", e)
        list(pool.map(one, keys))
        if time.time() < yahoo_cool[0]:
            time.sleep(4)                                    # Yahoo is complaining: go slow for a while
        else:
            time.sleep(0.5 if market_status() == "OPEN" else 10)


class Handler(BaseHTTPRequestHandler):
    def _send(self, code, ctype, body):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        if len(body) > 2000 and "gzip" in (self.headers.get("Accept-Encoding") or "") and ctype.startswith(("application/json", "text/")):
            body = gzip.compress(body, 4)                    # the chart JSON is 150-400 KB; gzip makes it ~6x smaller
            self.send_header("Content-Encoding", "gzip")
        self.send_header("Vary", "Accept-Encoding")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_HEAD(self):
        """Uptime monitors (UptimeRobot free) ping with HEAD, not GET."""
        u = urlparse(self.path)
        ok = u.path in ("/", "/index.html", "/healthz")
        self.send_response(200 if ok else 404)
        self.send_header("Content-Type", "text/plain")
        self.send_header("Content-Length", "2" if u.path == "/healthz" else "0")
        self.send_header("Cache-Control", "no-store")
        self.end_headers()

    def do_GET(self):
        u = urlparse(self.path)
        if u.path in ("/", "/index.html"):
            self._send(200, "text/html; charset=utf-8", PAGE.encode("utf-8"))
        elif u.path == "/data":
            q = parse_qs(u.query)
            tf = q.get("tf", ["15m"])[0]
            if tf not in TFS:
                tf = "15m"
            sym = clean_sym(q.get("sym", [DEFAULT_SYM])[0])
            k = f"{sym}|{tf}"
            force = "force" in q
            active[k] = time.time()
            c = cache.get(k)
            if force or c is None:
                with lock_for(k):
                    try:
                        c = cache[k] = {"json": build_json(tf, sym), "t": time.time()}
                    except Exception as e:
                        print("Data error:", e)
                        if c is None:
                            self._send(200, "application/json", json.dumps({"error": str(e)}).encode("utf-8"))
                            return
            body = c["json"].encode("utf-8")
            self._send(200, "application/json", body)
        elif u.path == "/manifest.json":
            m = {"name": "Nifty Live", "short_name": "Nifty Live", "start_url": "/", "display": "standalone",
                 "background_color": "#ffffff", "theme_color": "#ffffff",
                 "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
                           {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"}]}
            self._send(200, "application/manifest+json", json.dumps(m).encode("utf-8"))
        elif u.path in ("/icon-192.png", "/icon-512.png", "/favicon.ico"):
            self._send(200, "image/png", ICON_512 if u.path == "/icon-512.png" else ICON_192)
        elif u.path == "/live":
            q = parse_qs(u.query)
            tf = q.get("tf", ["15m"])[0]
            if tf not in TFS:
                tf = "15m"
            sym = clean_sym(q.get("sym", [DEFAULT_SYM])[0])
            k = f"{sym}|{tf}"
            active[k] = time.time()
            c = live_cache.get(k)
            if c is None or time.time() - c["t"] > 6 or "force" in q:
                with lock_for(k):
                    try:
                        c = live_cache[k] = {"json": build_live(tf, sym, fetch(tf, sym)), "t": time.time()}
                    except Exception as e:
                        if c is None:
                            self._send(200, "application/json", json.dumps({"error": str(e)}).encode("utf-8"))
                            return
            self._send(200, "application/json", c["json"].encode("utf-8"))
        elif u.path == "/news":
            sym = clean_sym(parse_qs(u.query).get("sym", [DEFAULT_SYM])[0])
            self._send(200, "application/json", json.dumps(news_view(sym)).encode("utf-8"))
        elif u.path == "/journal":
            q = parse_qs(u.query)
            tfq = q.get("tf", ["1h"])[0]
            try:
                days = max(0, min(int(q.get("days", ["30"])[0]), 3650))
            except ValueError:
                days = 30
            if time.time() - jmeta["updated"] > 120 and not jupd_lock.locked():
                journal_refresh()
            self._send(200, "application/json", json.dumps(journal_view(tfq, days)).encode("utf-8"))
        elif u.path == "/journal.csv":
            body = journal_csv().encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/csv; charset=utf-8")
            self.send_header("Content-Disposition", 'attachment; filename="nifty_journal.csv"')
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        elif u.path == "/alerts":
            self._send(200, "application/json", json.dumps(alerts_info()).encode("utf-8"))
        elif u.path == "/test-alert":
            self._send(200, "application/json", json.dumps(test_alert()).encode("utf-8"))
        elif u.path == "/healthz":
            self._send(200, "text/plain", b"ok")
        elif u.path == "/plan":
            q = parse_qs(u.query)
            if "force" in q:
                plan_cache.clear()
            ptf = q.get("tf", [PLAN_TF])[0]
            if ptf not in PLAN_TFS:
                ptf = PLAN_TF
            try:
                body = json.dumps(make_plan(ptf)).encode("utf-8")
            except Exception as e:
                body = json.dumps({"error": str(e)}).encode("utf-8")
            self._send(200, "application/json", body)
        elif u.path == "/bias":
            q = parse_qs(u.query)
            try:
                body = json.dumps(bias_for(clean_sym(q.get("sym", [DEFAULT_SYM])[0]), "force" in q)).encode("utf-8")
            except Exception as e:
                body = json.dumps({"error": str(e)}).encode("utf-8")
            self._send(200, "application/json", body)
        elif u.path == "/signals":
            q = parse_qs(u.query)
            if "force" in q:
                raw.clear()
            sym = clean_sym(q.get("sym", [DEFAULT_SYM])[0])
            with sig_lock:
                body = json.dumps(all_signals(sym)).encode("utf-8")
            self._send(200, "application/json", body)
        elif u.path == "/quotes":
            names = [clean_sym(x) for x in parse_qs(u.query).get("syms", [""])[0].split(",") if x.strip()][:30]
            names = list(dict.fromkeys(names))
            with ThreadPoolExecutor(max_workers=8) as ex:
                out = list(ex.map(quote, names))
            self._send(200, "application/json", json.dumps(out).encode("utf-8"))
        else:
            self.send_error(404)

    def log_message(self, *args):
        pass


def lan_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "PC-IP"


if __name__ == "__main__":
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"NIFTY 50 LIVE chart:  http://localhost:{PORT}")
    if HOST == "0.0.0.0" and not CLOUD:
        print(f"Phone (same WiFi): http://{lan_ip()}:{PORT}")
    print("Stop: Ctrl + C")
    threading.Thread(target=refresher, daemon=True).start()
    journal_load()
    threading.Thread(target=news_loop, daemon=True).start()
    threading.Thread(target=journal_loop, daemon=True).start()
    print("Signal journal ON (file: %s)" % JOURNAL_FILE)
    print("Phone alerts ON for " + ", ".join(ALERT_TFS) if alerts_enabled() else "Phone alerts OFF (set NTFY_TOPIC or Telegram to turn on)")
    if not CLOUD:
        threading.Timer(1.0, lambda: webbrowser.open(f"http://localhost:{PORT}")).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("Stopped.")
